// Parsear resposta do Graph API Excel - estrutura: {values: [[row1_col1, row1_col2, ...], ...]}
const data = $input.first().json;
if (!data.values || data.values.length <= 1) {
  return [{json: {ID: '__NENHUM__'}}];
}
const headers = data.values[0];
const rows = data.values.slice(1);
const items = rows.map(row => {
  const obj = {};
  headers.forEach((h, i) => { obj[String(h)] = row[i]; });
  return {json: obj};
});
return items.length > 0 ? items : [{json: {ID: '__NENHUM__'}}];

// Filtra incidentes que ainda NAO foram processados
const todosInc = $('Parsear Incidentes').all().map(i => i.json);
const processados = new Set(
  $input.all().map(i => String(i.json.ID || '')).filter(id => id && id !== '__NENHUM__')
);
const novos = todosInc.filter(i => i.ID && !processados.has(String(i.ID)));

if (!novos.length) {
  return [{json: {
    tem_novos: false,
    total_novos: 0,
    timestamp_analise: new Date().toISOString(),
    mensagem: 'Nenhum incidente novo esta semana. Total historico: ' + todosInc.length + ' incidentes.'
  }}];
}

console.log('Encontrados ' + novos.length + ' incidentes novos para processar.');
return novos.map(i => ({json: {...i, tem_novos: true, timestamp_analise: new Date().toISOString()}}));

const data = $input.first().json;
if (!data.values || data.values.length <= 1) return [{json: {Part_Number: '__NENHUM__', Familia: 'DESCONHECIDA'}}];
const headers = data.values[0];
const rows = data.values.slice(1);
return rows.map(row => {
  const obj = {};
  headers.forEach((h, i) => { obj[String(h)] = row[i]; });
  return {json: obj};
});

const data = $input.first().json;
if (!data.values || data.values.length <= 1) return [{json: {Pedido_ID: '__NENHUM__'}}];
const headers = data.values[0];
const rows = data.values.slice(1);
return rows.map(row => {
  const obj = {};
  headers.forEach((h, i) => { obj[String(h)] = row[i]; });
  return {json: obj};
});

// Enriquece o incidente com familia, historico e monta prompts para a IA
const inc = $input.first().json;
const todosInc = $('Parsear Incidentes').all().map(i => i.json);
const familias = $('Parsear Familias').all().map(f => f.json);
const pedidos = $('Parsear Pedidos').all().map(p => p.json);

// Mapear familias
const famMap = {};
familias.forEach(f => {
  if (f.Part_Number && f.Familia) famMap[String(f.Part_Number).trim()] = String(f.Familia).trim();
});
const familia = famMap[String(inc.Part_Number || '').trim()] || 'FAMILIA_NAO_MAPEADA';

// Historico do fornecedor e familia
const incForn = todosInc.filter(i => i.Cod_Fornecedor === inc.Cod_Fornecedor);
const incFam = todosInc.filter(i => famMap[String(i.Part_Number || '').trim()] === familia && familia !== 'FAMILIA_NAO_MAPEADA');

// Pedidos dos proximos 90 dias para este part/familia
const agora = new Date();
const pedFiltrados = pedidos.filter(p => {
  const diff = (new Date(p.Data_Entrega_Prevista) - agora) / 86400000;
  return (p.Part_Number === inc.Part_Number || famMap[String(p.Part_Number||'').trim()] === familia) && diff > 0 && diff <= 90;
});

// Verificar se e ocorrencia nova (novo fornecedor, part novo, familia nova)
const isNovoFornecedor = incForn.length === 0;
const isNovaFamilia = incFam.length === 0 && familia !== 'FAMILIA_NAO_MAPEADA';
const isOcorrenciaNova = isNovoFornecedor || isNovaFamilia;

// Prompt sistema para classificacao 14Q-Basics Bosch
const sysPrompt14Q = 'Voce eh especialista em qualidade automotiva com conhecimento profundo da metodologia Bosch 14Q-Basics (Value Stream Q-Basics). Os 14 principios sao: Q1=Plano de Controle, Q2=FMEA, Q3=Poka-Yoke/Mistake Proofing, Q4=SPC/CEP, Q5=MSA/Analise Sistema Medicao, Q6=PPAP/APQP, Q7=Reacao ao Cliente/Customer Complaint, Q8=Qualidade na Fonte, Q9=Manutencao Preventiva, Q10=Treinamento de Operadores, Q11=Gestao de Mudancas, Q12=Auditorias de Processo, Q13=Gestao de Fornecedores/Sub-fornecedores, Q14=Logistica e Embalagem. Analise o incidente e classifique na categoria 14Q mais adequada. Responda SOMENTE em JSON valido sem markdown: {"categoria_14q":"Q[N] - [Nome]","numero_q":[N],"confianca":[0.0-1.0],"justificativa":"[explicacao detalhada]","categorias_secundarias":["Q[N] - [Nome]"],"acoes_preventivas":["acao1","acao2","acao3"]}';

const userPrompt14Q = 'Analise e classifique este incidente 8D nos 14Q-Basics Bosch:\n\nFornecedor: ' + inc.Fornecedor + ' (Cod: ' + inc.Cod_Fornecedor + ')\nPart Number: ' + inc.Part_Number + ' (Familia: ' + familia + ')\nData da Ocorrencia: ' + inc.Data + '\nD3 - Contencao: ' + (inc.D3 || 'N/A') + '\nD4 - Causa Raiz: ' + (inc.Causa_Raiz || inc.D4 || 'N/A') + '\nD5 - Acoes Permanentes: ' + (inc.D5 || 'N/A') + '\nD6 - Implementacao: ' + (inc.D6 || 'N/A') + '\nDescricao do Problema: ' + inc.Descricao_Problema + '\n\nContexto historico:\n- Total de ocorrencias neste fornecedor: ' + incForn.length + '\n- Total de ocorrencias nesta familia (' + familia + '): ' + incFam.length + '\n- E ocorrencia nova/inedita: ' + isOcorrenciaNova + '\n\nClassifique o 14Q que melhor explica a CAUSA RAIZ do problema.';

return [{
  json: {
    ...inc,
    familia,
    total_falhas_fornecedor: incForn.length,
    total_falhas_familia: incFam.length,
    pedidos_proximos_90d: pedFiltrados,
    is_ocorrencia_nova: isOcorrenciaNova,
    is_novo_fornecedor: isNovoFornecedor,
    is_nova_familia: isNovaFamilia,
    historico_tipos_14q: [...new Set(incForn.map(i => i.categoria_14q).filter(Boolean))],
    system_prompt_14q: sysPrompt14Q,
    user_prompt_14q: userPrompt14Q
  }
}];

// Prepara o corpo da requisicao para OpenAI - preserva TODOS os dados do incidente
const inc = $input.first().json;
return [{
  json: {
    ...inc,
    _openai_body_14q: {
      model: 'gpt-4',
      response_format: {type: 'json_object'},
      messages: [
        {role: 'system', content: inc.system_prompt_14q},
        {role: 'user', content: inc.user_prompt_14q}
      ],
      temperature: 0.1,
      max_tokens: 2000
    }
  }
}];

// Extrai a classificacao 14Q da resposta OpenAI e prepara o prompt para o checklist LPC
const resp = $input.first().json;
const inc = $('Preparar Request 14Q').first().json;

let c = {categoria_14q: 'Q7 - Reacao ao Cliente', numero_q: 7, confianca: 0.5, justificativa: 'Erro ao parsear resposta da IA', categorias_secundarias: [], acoes_preventivas: []};
try {
  const content = resp.choices && resp.choices[0] && resp.choices[0].message ? resp.choices[0].message.content : '{}';
  c = JSON.parse(content);
} catch(e) {
  console.error('Erro ao parsear resposta 14Q:', e.message);
}

// Prompt para gerar o checklist LPC
const sysLPC = 'Voce eh especialista em Layer Process Confirmation (LPC / Auditoria por Camadas) no setor automotivo. Com base no incidente e classificacao 14Q, crie um checklist detalhado e especifico para o fornecedor executar durante a producao. O checklist deve prevenir a reocorrencia da falha identificada. Responda SOMENTE em JSON valido sem markdown: {"checklist_titulo":"[titulo especifico]","objetivo":"[objetivo do checklist]","itens":[{"numero":1,"categoria":"[categoria]","ponto_verificacao":"[o que verificar especificamente]","criterio_aceite":"[criterio quantificavel de OK]","frequencia":"[Por peca/Por lote/Por turno/etc]","responsavel":"[Operador/Supervisor/Qualidade]","referencia_documento":"[doc de referencia se aplicavel]"}],"observacoes_gerais":"[obs importantes]"}';

const usrLPC = 'Crie um checklist Layer Process Confirmation (LPC) especifico para prevenir a reocorrencia desta falha:\n\nFornecedor: ' + inc.Fornecedor + '\nPart Number: ' + inc.Part_Number + ' (Familia: ' + inc.familia + ')\nProblema ocorrido: ' + inc.Descricao_Problema + '\nCausa Raiz (8D): ' + (inc.Causa_Raiz || inc.D4 || 'N/A') + '\nClassificacao 14Q: ' + c.categoria_14q + ' (Confianca: ' + Math.round((c.confianca||0)*100) + '%)\nJustificativa: ' + (c.justificativa || '') + '\nAcoes Preventivas 14Q: ' + (c.acoes_preventivas || []).join(', ') + '\n\nGere um checklist com MINIMO de 8 pontos de verificacao ESPECIFICOS E DETALHADOS para este tipo de falha. Cada ponto deve ter criterio de aceite quantificavel.';

return [{
  json: {
    ...inc,
    categoria_14q: c.categoria_14q || 'Q7 - Reacao ao Cliente',
    numero_q: c.numero_q || 7,
    confianca_14q: c.confianca || 0.5,
    confianca_14q_pct: Math.round((c.confianca || 0.5) * 100),
    justificativa_14q: c.justificativa || '',
    categorias_secundarias: c.categorias_secundarias || [],
    acoes_preventivas_14q: c.acoes_preventivas || [],
    system_prompt_lpc: sysLPC,
    user_prompt_lpc: usrLPC,
    _openai_body_lpc: {
      model: 'gpt-4',
      response_format: {type: 'json_object'},
      messages: [
        {role: 'system', content: sysLPC},
        {role: 'user', content: usrLPC}
      ],
      temperature: 0.2,
      max_tokens: 3000
    }
  }
}];

// Extrai checklist LPC + calcula todos os 3 metodos estatisticos + cruzamento com pedidos
const lpcResp = $input.first().json;
const inc = $('Extrair 14Q e Preparar LPC').first().json;
const todosInc = $('Parsear Incidentes').all().map(i => i.json);

// === EXTRAIR CHECKLIST LPC ===
let cl = {checklist_titulo: 'LPC - ' + inc.Part_Number, objetivo: 'Prevenir reocorrencia de falha', itens: [{numero:1,categoria:'Processo',ponto_verificacao:'Verificar parametros criticos do processo',criterio_aceite:'Dentro dos limites especificados',frequencia:'Por lote',responsavel:'Operador',referencia_documento:'N/A'}], observacoes_gerais: 'Checklist padrao - customizar para o produto especifico'};
try {
  const content = lpcResp.choices && lpcResp.choices[0] ? lpcResp.choices[0].message.content : '{}';
  cl = JSON.parse(content);
} catch(e) { console.error('Erro ao parsear checklist LPC:', e.message); }

// === METODO 1: PPM (Parts Per Million) ===
const incForn = todosInc.filter(i => i.Cod_Fornecedor === inc.Cod_Fornecedor);
const totalFalhas = Math.max(incForn.length, 1);
// IMPORTANTE: totalEntregas deve ser obtido do sistema ERP. Aqui usamos estimativa.
// Para resultado preciso, adicione uma coluna 'Total_Pecas_Entregues' na aba do fornecedor
const totalEntregas = Math.max(totalFalhas * 5000, 10000);
const ppm = (totalFalhas / totalEntregas) * 1000000;
const ppmNorm = Math.min(ppm / 1000, 1.0); // 1000 PPM = risco maximo (1.0)
const histMin = totalFalhas < 3; // Alerta se historico insuficiente

// === METODO 2: TENDENCIA TEMPORAL (Media Movel 6 Meses) ===
const agora = new Date();
const m3ago = new Date(agora.getTime() - 90 * 86400000);
const m6ago = new Date(agora.getTime() - 180 * 86400000);
const nPrim = incForn.filter(i => { const d = new Date(i.Data); return d >= m6ago && d < m3ago; }).length;
const nRec = incForn.filter(i => new Date(i.Data) >= m3ago).length;
const delta = nRec - nPrim;
const tendTexto = delta > 0 ? 'CRESCENTE (+' + delta + ' vs periodo anterior)' : delta < 0 ? 'DECRESCENTE (' + delta + ' vs periodo anterior)' : 'ESTAVEL';
const tendNorm = Math.max(0, Math.min(1, 0.5 + delta * 0.1));

// === METODO 3: PROBABILIDADE BAYESIANA (com suavizacao de Laplace) ===
const falhasTipo = incForn.filter(i => i.categoria_14q === inc.categoria_14q).length;
// P(falha|historico) = (falhas_tipo + 1) / (total_falhas + 2)  -- suavizacao de Laplace
const probBayes = (falhasTipo + 1) / (totalFalhas + 2);

// === PROBABILIDADE FINAL (media ponderada) ===
// PPM: 30% | Tendencia: 40% | Bayesiana: 30%
const probFinal = (ppmNorm * 0.30) + (tendNorm * 0.40) + (probBayes * 0.30);
const probPct = Math.round(probFinal * 100);

// === CRUZAMENTO COM PEDIDOS FUTUROS ===
const pedidos = inc.pedidos_proximos_90d || [];
const threshold = 0.30; // 30% = limiar de alerta - AJUSTE conforme necessidade
const porMes = {1:{pedidos:[],qtd:0,risco:0},2:{pedidos:[],qtd:0,risco:0},3:{pedidos:[],qtd:0,risco:0}};
pedidos.forEach(p => {
  const diff = (new Date(p.Data_Entrega_Prevista) - agora) / 86400000;
  const mes = diff <= 30 ? 1 : diff <= 60 ? 2 : 3;
  // Fator de decaimento: incerteza aumenta com a distancia temporal
  const fator = mes === 1 ? 1.0 : mes === 2 ? 0.85 : 0.70;
  const risco = probFinal * fator;
  porMes[mes].pedidos.push({id:p.Pedido_ID,data:p.Data_Entrega_Prevista,qtd:p.Qtd,risco_pct:Math.round(risco*100)});
  porMes[mes].qtd += Number(p.Qtd) || 0;
  porMes[mes].risco = Math.max(porMes[mes].risco, risco);
});
const riscoMax = Math.max(porMes[1].risco, porMes[2].risco, porMes[3].risco);
const alertar = riscoMax > threshold;

// === TEXTO EXPLICATIVO DOS CALCULOS (para revisao humana) ===
const expl = [
  '=== ANALISE ESTATISTICA DETALHADA ===',
  'Data: ' + agora.toISOString(),
  'Fornecedor: ' + inc.Fornecedor + ' | Part: ' + inc.Part_Number + ' | Familia: ' + inc.familia,
  '',
  'METODO 1 - PPM / Parts Per Million (Peso: 30%):',
  '  Formula: PPM = (falhas / entregas) x 1.000.000',
  '  Falhas historicas do fornecedor: ' + totalFalhas,
  '  Total pecas entregues (estimado): ' + totalEntregas,
  '  ATENCAO: Para calculo preciso do PPM, obtenha o numero real de pecas entregues do ERP!',
  '  PPM calculado: ' + Math.round(ppm) + ' PPM',
  '  Contribuicao normalizada: ' + Math.round(ppmNorm * 100) + '%',
  histMin ? '  *** AVISO: Historico insuficiente (<3 ocorrencias). Resultado menos confiavel. ***' : '  Historico adequado (' + totalFalhas + ' ocorrencias).',
  '',
  'METODO 2 - TENDENCIA TEMPORAL - Media Movel 6 Meses (Peso: 40%):',
  '  Periodo de analise: ultimos 6 meses divididos em 2 semestres',
  '  Ocorrencias meses 4-6 (mais antigo): ' + nPrim,
  '  Ocorrencias meses 1-3 (mais recente): ' + nRec,
  '  Variacao: ' + (delta > 0 ? '+' : '') + delta + ' incidentes',
  '  Tendencia: ' + tendTexto,
  '  Contribuicao normalizada: ' + Math.round(tendNorm * 100) + '%',
  '  (50% = estavel; >50% = piorando; <50% = melhorando)',
  '',
  'METODO 3 - PROBABILIDADE BAYESIANA com Suavizacao de Laplace (Peso: 30%):',
  '  Formula: P(falha_tipo) = (n_falhas_tipo + 1) / (total_falhas_fornecedor + 2)',
  '  Tipo analisado: ' + inc.categoria_14q,
  '  Falhas deste tipo: ' + falhasTipo,
  '  Calculo: (' + falhasTipo + ' + 1) / (' + totalFalhas + ' + 2) = ' + Math.round(probBayes * 100) + '%',
  '  A suavizacao (+1/+2) evita probabilidade zero em casos sem historico especifico',
  '',
  'PROBABILIDADE FINAL (media ponderada):',
  '  Formula: P_final = PPM_norm(0.30) + Tendencia(0.40) + Bayesiana(0.30)',
  '  Calculo: (' + Math.round(ppmNorm*100) + '% x 0.30) + (' + Math.round(tendNorm*100) + '% x 0.40) + (' + Math.round(probBayes*100) + '% x 0.30)',
  '  = ' + Math.round(ppmNorm*30) + '% + ' + Math.round(tendNorm*40) + '% + ' + Math.round(probBayes*30) + '%',
  '  PROBABILIDADE FINAL: ' + probPct + '%',
  '  LIMIAR DE ALERTA: ' + Math.round(threshold*100) + '%',
  '  STATUS: ' + (alertar ? '*** ALERTA - RISCO ACIMA DO LIMIAR ***' : 'DENTRO DO LIMITE - MONITORAMENTO'),
  '',
  'CRUZAMENTO COM PEDIDOS FUTUROS (proximos 90 dias):',
  '  Part Number: ' + inc.Part_Number + ' | Familia: ' + inc.familia,
  '  Mes 1 (0-30 dias): ' + porMes[1].pedidos.length + ' pedido(s) | ' + porMes[1].qtd + ' pecas | Risco: ' + Math.round(porMes[1].risco*100) + '% (fator 1.0)',
  '  Mes 2 (31-60 dias): ' + porMes[2].pedidos.length + ' pedido(s) | ' + porMes[2].qtd + ' pecas | Risco: ' + Math.round(porMes[2].risco*100) + '% (fator 0.85)',
  '  Mes 3 (61-90 dias): ' + porMes[3].pedidos.length + ' pedido(s) | ' + porMes[3].qtd + ' pecas | Risco: ' + Math.round(porMes[3].risco*100) + '% (fator 0.70)',
  '  Risco Maximo nos 90 dias: ' + Math.round(riscoMax*100) + '%'
].join('\n');

// Formatar checklist como texto legivel
const checklistTexto = (cl.itens || []).map((it, idx) =>
  (idx+1) + '. [' + (it.categoria||'Geral') + '] ' + it.ponto_verificacao + '\n   Criterio: ' + it.criterio_aceite + '\n   Freq: ' + it.frequencia + ' | Resp: ' + it.responsavel
).join('\n\n');

// Payload para salvar na aba Analises do SharePoint (linha a ser inserida na tabela)
const payloadAnalise = {
  values: [[
    String(inc.ID || ''),
    agora.toISOString(),
    String(inc.Fornecedor || ''),
    String(inc.Cod_Fornecedor || ''),
    String(inc.Part_Number || ''),
    String(inc.familia || ''),
    String(inc.categoria_14q || ''),
    String(inc.confianca_14q_pct || 0) + '%',
    String(Math.round(ppm)),
    String(tendTexto),
    String(Math.round(probBayes*100)) + '%',
    String(probPct) + '%',
    String(alertar ? 'ALERTA_ENVIADO' : 'MONITORAMENTO'),
    String(cl.checklist_titulo || ''),
    String(expl),
    String(inc.is_ocorrencia_nova ? 'SIM - NOVA OCORRENCIA' : 'NAO')
  ]]
};

return [{
  json: {
    ...inc,
    checklist_titulo: cl.checklist_titulo || 'LPC - ' + inc.Part_Number,
    checklist_objetivo: cl.objetivo || '',
    checklist_itens: cl.itens || [],
    checklist_observacoes: cl.observacoes_gerais || '',
    checklist_texto_formatado: checklistTexto,
    ppm: Math.round(ppm),
    ppm_normalizado: ppmNorm,
    tendencia: tendTexto,
    tendencia_normalizada: tendNorm,
    prob_bayesiana: probBayes,
    prob_bayesiana_pct: Math.round(probBayes * 100),
    prob_final: probFinal,
    prob_final_pct: probPct,
    historico_insuficiente: histMin,
    pedidos_por_mes: porMes,
    risco_maximo_pct: Math.round(riscoMax * 100),
    threshold_pct: Math.round(threshold * 100),
    alertar,
    explicacao_calculo: expl,
    payload_analise: payloadAnalise
  }
}];
